ALTER TABLE public.posts ADD COLUMN visibility_notified_at timestamptz;
CREATE OR REPLACE FUNCTION public.match_post() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m record; BEGIN IF NEW.visible_after>now() OR NEW.job_expires_at<=now() THEN RETURN NEW; END IF; FOR m IN SELECT p.* FROM public.posts p WHERE public.posts_match_area(NEW,p) AND (p.visible_after IS NULL OR p.visible_after<=now()) AND (p.job_expires_at IS NULL OR p.job_expires_at>now()) LOOP IF public.can_notify(NEW.user_id) THEN INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(NEW.user_id,NEW.id,m.id,'మ్యాచ్ దొరికింది! Match found: '||m.title); END IF; IF public.can_notify(m.user_id) THEN INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(m.user_id,m.id,NEW.id,'మ్యాచ్ దొరికింది! Match found: '||NEW.title); END IF; END LOOP; RETURN NEW; END $$;
CREATE FUNCTION public.dispatch_visible_post_matches() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; m public.posts; processed integer:=0; BEGIN
FOR p IN SELECT * FROM public.posts WHERE visible_after<=now() AND visibility_notified_at IS NULL AND status='active' AND (job_expires_at IS NULL OR job_expires_at>now()) ORDER BY visible_after LIMIT 20 FOR UPDATE SKIP LOCKED LOOP
FOR m IN SELECT * FROM public.posts candidate WHERE public.posts_match_area(p,candidate) AND (candidate.visible_after IS NULL OR candidate.visible_after<=now()) AND (candidate.job_expires_at IS NULL OR candidate.job_expires_at>now()) LOOP
IF public.can_notify(p.user_id) AND NOT EXISTS(SELECT 1 FROM public.notifications WHERE user_id=p.user_id AND post_id=p.id AND matched_post_id=m.id) THEN INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(p.user_id,p.id,m.id,'మ్యాచ్ దొరికింది · Match found: '||m.title); END IF;
IF public.can_notify(m.user_id) AND NOT EXISTS(SELECT 1 FROM public.notifications WHERE user_id=m.user_id AND post_id=m.id AND matched_post_id=p.id) THEN INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(m.user_id,m.id,p.id,'మ్యాచ్ దొరికింది · Match found: '||p.title); END IF; END LOOP;
UPDATE public.posts SET visibility_notified_at=now() WHERE id=p.id; processed:=processed+1; END LOOP; RETURN processed; END $$;
REVOKE ALL ON FUNCTION public.dispatch_visible_post_matches() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.dispatch_visible_post_matches() TO service_role;